/** Minimal, bounded PNG text-chunk parser. This is a starter, NOT a complete image forensics engine.
 * Supports tEXt, uncompressed iTXt. Compressed zTXt/iTXt are left for Codex P1.
 * No pixels or alpha steganography are decoded here. Never assert 'no metadata'
 * means the image was not generated by AI.
 */
export const MAX_IMAGE_BYTES = 48 * 1024 * 1024;
export const MAX_TEXT_BYTES = 2 * 1024 * 1024;
const sig = [137, 80, 78, 71, 13, 10, 26, 10];
const utf8 = new TextDecoder('utf-8', { fatal: false });
const latin1 = new TextDecoder('iso-8859-1');

export function isPng(bytes: Uint8Array): boolean {
  return bytes.length >= 8 && sig.every((b, i) => bytes[i] === b);
}

function findZero(v: Uint8Array, start = 0): number {
  return v.indexOf(0, start);
}

export function parsePngTextChunks(data: Uint8Array): Record<string, string> {
  if (data.length > MAX_IMAGE_BYTES) throw new Error('too-large');
  if (!isPng(data)) throw new Error('not-png');
  const chunks: Record<string, string> = Object.create(null) as Record<string, string>;
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  let offset = 8;
  let totalTextBytes = 0;
  while (offset + 12 <= data.length) {
    const length = view.getUint32(offset, false);
    const end = offset + 12 + length;
    if (end > data.length || end < offset) throw new Error('malformed-png');
    const tag = String.fromCharCode(...data.subarray(offset + 4, offset + 8));
    const part = data.subarray(offset + 8, offset + 8 + length);
    if (tag === 'tEXt' || tag === 'iTXt') {
      totalTextBytes += part.length;
      if (totalTextBytes > MAX_TEXT_BYTES) throw new Error('text-too-large');
      const firstZero = findZero(part);
      if (firstZero > 0) {
        const name = latin1.decode(part.subarray(0, firstZero));
        if (name === '__proto__' || name === 'constructor') {
          // Do not trust arbitrary PNG key strings as object properties.
          offset = end;
          continue;
        }
        if (tag === 'tEXt') {
          chunks[name] = latin1.decode(part.subarray(firstZero + 1));
        } else {
          const compressionFlag = part[firstZero + 1];
          const afterHeader = firstZero + 3;
          const languageEnd = findZero(part, afterHeader);
          const translatedEnd = languageEnd < 0 ? -1 : findZero(part, languageEnd + 1);
          if (compressionFlag === 0 && translatedEnd >= 0) {
            chunks[name] = utf8.decode(part.subarray(translatedEnd + 1));
          }
        }
      }
    }
    offset = end;
    if (tag === 'IEND') break;
  }
  return chunks;
}
